module case_range_1(input logic clk, rst, en, output logic [3:0] value);
  always_ff @(posedge clk or posedge rst) begin
    case (rst)
      1'b1: value <= 0;
      1'b0: begin
        case (value) inside
          [0:3]: begin
            case (en)
              1'b1: value <= value + 1;
              1'b0: value <= value;
            endcase
          end
          [4:7]: begin
            case (en)
              1'b1: value <= value - 1;
              1'b0: value <= value;
            endcase
          end
          [8:11]: value <= 4'b0101;
          [12:15]: value <= 0;
        endcase
      end
    endcase
  end
endmodule,"module case_range_1_asserts  (input logic clk, rst, en, input logic [3:0] value)

