module case_histogram(input logic clk, rst, inc, dec, output logic [3:0] hist_bin);
    always_ff @(posedge clk or posedge rst) begin
        case(rst)
            1'b1: hist_bin <= 4'd0;
            1'b0: case(hist_bin) inside
                      [0:2]: case(inc)
                                 1'b1: hist_bin <= hist_bin + 1;
                                 1'b0: hist_bin <= hist_bin;
                                 default: hist_bin <= hist_bin;
                             endcase
                      [3:7]: begin
                                 // Handle inc condition with range check
                                 case(inc)
                                     1'b1: begin
                                               case(hist_bin < 4'd12)
                                                   1'b1: hist_bin <= hist_bin + 1;
                                                   1'b0: hist_bin <= hist_bin;
                                                   default: hist_bin <= hist_bin;
                                               endcase
                                           end
                                     1'b0: hist_bin <= hist_bin;
                                     default: hist_bin <= hist_bin;
                                 endcase
                                 // Handle dec condition with range check
                                 case(dec)
                                     1'b1: begin
                                               case(hist_bin > 4'd0)
                                                   1'b1: hist_bin <= hist_bin - 1;
                                                   1'b0: hist_bin <= hist_bin;
                                                   default: hist_bin <= hist_bin;
                                               endcase
                                           end
                                     1'b0: hist_bin <= hist_bin;
                                     default: hist_bin <= hist_bin;
                                 endcase
                             end
                      [8:12]: case(dec)
                                  1'b1: hist_bin <= hist_bin - 1;
                                  1'b0: hist_bin <= hist_bin;
                                  default: hist_bin <= hist_bin;
                              endcase
                      [13:15]: hist_bin <= 4'd7;
                  endcase
        endcase
    end
