module case_burst_len(input logic clk, rst, inc, dec, output logic [3:0] burst);
    always_ff @(posedge clk or posedge rst) begin
        case(rst)
            1'b1: burst <= 4'b0010;
            1'b0: case(burst) inside
                      [1:2]: case(inc)
                                 1'b1: burst <= burst + 1;
                                 1'b0: burst <= burst;
                                 default: burst <= burst;
                             endcase
                      [3:6]: begin
                                 // Handle inc condition with max check
                                 case(inc)
                                     1'b1: begin
                                               case(burst < 4'd8)
                                                   1'b1: burst <= burst + 1;
                                                   1'b0: burst <= burst;
                                                   default: burst <= burst;
                                               endcase
                                           end
                                     1'b0: burst <= burst;
                                     default: burst <= burst;
                                 endcase
                                 // Handle dec condition with min check
                                 case(dec)
                                     1'b1: begin
                                               case(burst > 4'd1)
                                                   1'b1: burst <= burst - 1;
                                                   1'b0: burst <= burst;
                                                   default: burst <= burst;
                                               endcase
                                           end
                                     1'b0: burst <= burst;
                                     default: burst <= burst;
                                 endcase
                             end
                      [7:8]: case(dec)
                                 1'b1: burst <= burst - 1;
                                 1'b0: burst <= burst;
                                 default: burst <= burst;
                             endcase
                      [9:15]: burst <= 4'b0010;
                      0: burst <= 4'b0010;
                  endcase
        endcase
    end
endmodule,"module case_burst_len_asserts  (input logic clk, rst, inc, dec, input logic [3:0] burst)

