module runt_pulse_detector (
    input logic clk,
    input logic rst_n,
    input logic signal_in,
    input logic [3:0] min_width,
    output logic runt_detected
);

typedef enum logic [2:0] {IDLE, PULSE_LOW, PULSE_HIGH, CHECK} state_t;
state_t state, next_state;
logic [3:0] pulse_width;

always_ff @(posedge clk or negedge rst_n) begin
    case(rst_n)
        1'b0: begin
            state <= IDLE;
            pulse_width <= 4'b0;
        end
        1'b1: begin
            state <= next_state;
            case(state)
                PULSE_LOW, PULSE_HIGH: pulse_width <= pulse_width + 1;
                default: pulse_width <= 4'b0;
            endcase
        end
        default: begin
            state <= IDLE;
            pulse_width <= 4'b0;
        end
    endcase
end

always_comb begin
    next_state = state;
    runt_detected = 1'b0;

    case (state)
        IDLE: begin
            case(signal_in)
                1'b1: next_state = PULSE_HIGH;
                1'b0: next_state = PULSE_LOW;
                default: next_state = state;
            endcase
        end

        PULSE_HIGH: begin
            case(signal_in)
                1'b0: begin
                    next_state = CHECK;
                    // Check if pulse was too short
                    case(pulse_width < min_width)
                        1'b1: runt_detected = 1'b1;  // Immediate detection
                        1'b0: runt_detected = 1'b0;
                        default: runt_detected = 1'b0;
                    endcase
                end
                1'b1: begin
                    next_state = state;
                    runt_detected = 1'b0;
                end
                default: begin
                    next_state = state;
                    runt_detected = 1'b0;
                end
            endcase
        end

        PULSE_LOW: begin
            case(signal_in)
                1'b1: begin
                    next_state = CHECK;
                    // Check if pulse was too short
                    case(pulse_width < min_width)
                        1'b1: runt_detected = 1'b1;  // Immediate detection
                        1'b0: runt_detected = 1'b0;
                        default: runt_detected = 1'b0;
                    endcase
                end
                1'b0: begin
                    next_state = state;
                    runt_detected = 1'b0;
                end
                default: begin
                    next_state = state;
                    runt_detected = 1'b0;
                end
            endcase
        end

        CHECK: begin
            // Return to IDLE after one cycle
            next_state = IDLE;
            runt_detected = 1'b0;
        end

        default: begin
            next_state = IDLE;
            runt_detected = 1'b0;
        end
    endcase
end

endmodule,"module runt_pulse_detector_asserts  (input logic clk,

module tcp_congestion_control (
    input logic clk,
    input logic rst_n,
    input logic ack_received,
    input logic timeout_event,
    input logic [15:0] rtt_measurement,
    input logic [2:0] duplicate_acks,
    output logic [15:0] congestion_window,
    output logic [15:0] slow_start_threshold,
    output logic [1:0] phase  // 00: SLOW_START, 01: CONG_AVOID, 10: FAST_RECOVERY
);

typedef enum logic [2:0] {
    SLOW_START,
    CONGESTION_AVOIDANCE,
    FAST_RECOVERY,
    FAST_RETRANSMIT,
    TIMEOUT_WAIT,
    PROBE
} state_t;

state_t state, next_state;
logic [15:0] cwnd, next_cwnd;
logic [15:0] ssthresh, next_ssthresh;
logic [3:0] ack_counter, next_ack_counter;
logic [31:0] rto_counter, next_rto_counter;
logic [15:0] min_rtt, next_min_rtt;
logic [15:0] avg_rtt, next_avg_rtt;

// Sequential logic
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: begin
            state <= SLOW_START;
            cwnd <= 16'd1;
            ssthresh <= 16'd65535;
            ack_counter <= 4'b0;
            rto_counter <= 32'b0;
            min_rtt <= 16'hFFFF;
            avg_rtt <= 16'd100;
        end
        1'b1: begin
            state <= next_state;
            cwnd <= next_cwnd;
            ssthresh <= next_ssthresh;
            ack_counter <= next_ack_counter;
            rto_counter <= next_rto_counter;
            min_rtt <= next_min_rtt;
            avg_rtt <= next_avg_rtt;
        end
    endcase
end

// Combinational logic
always_comb begin
    // Default assignments
    next_state = state;
    next_cwnd = cwnd;
    next_ssthresh = ssthresh;
    next_ack_counter = ack_counter;
    next_rto_counter = rto_counter;
    next_min_rtt = min_rtt;
    next_avg_rtt = avg_rtt;

    congestion_window = cwnd;
    slow_start_threshold = ssthresh;
    phase = 2'b00;

    // Update RTT measurements
    case (rtt_measurement < min_rtt)
      	(1'b1): next_min_rtt = rtt_measurement;
        default: next_min_rtt = min_rtt;
    endcase

    next_avg_rtt = (avg_rtt * 7 + rtt_measurement) >> 3;

    // FSM logic
    case (state)
        SLOW_START: begin
            phase = 2'b00;

            // Check for packet loss
            case (duplicate_acks >= 3'd3)
                1'b1: begin
                    next_state = FAST_RECOVERY;
                    next_ssthresh = cwnd >> 1;
                end
            endcase

            // ACK handling
            case (ack_received)
                1'b1: begin
                    next_cwnd = cwnd + 1;
                    next_ack_counter = ack_counter + 1;
                    case (cwnd >= ssthresh)
                        1'b1: next_state = CONGESTION_AVOIDANCE;
                    endcase
                end
            endcase

            // RTT-based adaptation
            case (rtt_measurement > (avg_rtt + (avg_rtt >> 2)))
                1'b1: begin
                    next_ssthresh = cwnd;
                    next_state = CONGESTION_AVOIDANCE;
                end
            endcase
        end

        CONGESTION_AVOIDANCE: begin
            phase = 2'b01;

            // Packet loss detection
            case (duplicate_acks == 3'd3)
                1'b1: begin
                    next_state = FAST_RETRANSMIT;
                    next_ssthresh = cwnd >> 1;
                    next_cwnd = next_ssthresh + 3;
                end
            endcase

            // ACK handling
            case (ack_received)
                1'b1: begin
                    next_ack_counter = ack_counter + 1;
                    case (ack_counter == cwnd)
                        1'b1: begin
                            next_cwnd = cwnd + 1;
                            next_ack_counter = 4'b0;
                        end
                    endcase
                end
            endcase

            // Timeout handling
            case (timeout_event)
                1'b1: begin
                    next_ssthresh = cwnd >> 1;
                    next_cwnd = 16'd1;
                    next_state = TIMEOUT_WAIT;
                    next_rto_counter = 32'b0;
                end
            endcase
        end

        FAST_RECOVERY: begin
            phase = 2'b10;

            case (ack_received)
                1'b1: begin
                    next_cwnd = ssthresh;
                    next_state = CONGESTION_AVOIDANCE;
                end
            endcase

            case (duplicate_acks == 3'd3)
                1'b1: begin
                    next_state = FAST_RETRANSMIT;
                    next_ssthresh = cwnd >> 1;
                    next_cwnd = next_ssthresh + 3;
                end
            endcase
        end

        FAST_RETRANSMIT: begin
            phase = 2'b10;

            case (ack_received)
                1'b1: next_state = FAST_RECOVERY;
            endcase
        end

        TIMEOUT_WAIT: begin
            phase = 2'b00;

            next_rto_counter = rto_counter + 1;
            case ((rto_counter > (min_rtt * 2)) && ack_received)
                1'b1: next_state = SLOW_START;
                1'b0: begin
                    case ((rto_counter > (min_rtt * 2)) && !ack_received)
                        1'b1: next_state = PROBE;
                    endcase
                end
            endcase
        end

        PROBE: begin
            phase = 2'b00;

            next_cwnd = 16'd1;
            case (ack_received)
                1'b1: next_state = SLOW_START;
            endcase
        end
    endcase
end

endmodule,"module tcp_congestion_control_asserts  (input logic clk,

module spi_master_mealy (
    input logic clk,
    input logic rst_n,
    input logic start,
    input logic [7:0] tx_data,
    output logic sclk,
    output logic mosi,
    input logic miso,
    output logic [7:0] rx_data,
    output logic busy,
    output logic done
);

typedef enum logic [2:0] {IDLE, CLK_LOW, CLK_HIGH, DONE_ST} state_t;
state_t state, next_state;
logic [2:0] bit_count, next_bit_count;
logic [7:0] shift_reg, next_shift_reg;

// Sequential logic
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: begin
            state <= IDLE;
            bit_count <= 3'b0;
            shift_reg <= 8'b0;
        end
        1'b1: begin
            state <= next_state;
            bit_count <= next_bit_count;
            shift_reg <= next_shift_reg;
        end
    endcase
end

// Combinational logic
always_comb begin
    // Default assignments
    next_state = state;
    next_bit_count = bit_count;
    next_shift_reg = shift_reg;
    sclk = 1'b0;
    mosi = 1'b0;
    busy = 1'b1;
    done = 1'b0;
    rx_data = shift_reg;

    case (state)
        IDLE: begin
            busy = 1'b0;
            done = 1'b0;
            case (start)
                1'b1: begin
                    next_state = CLK_LOW;
                    next_shift_reg = tx_data;
                    next_bit_count = 3'b0;
                end
            endcase
        end

        CLK_LOW: begin
            // SCLK low phase
            sclk = 1'b0;
            mosi = shift_reg[7];  // Output MSB first

            case (bit_count == 3'b111)  // Last bit?
                1'b1: begin
                    // Last bit: sample final data and go to DONE
                    next_shift_reg = {shift_reg[6:0], miso};
                    next_state = DONE_ST;
                end
                1'b0: begin
                    // Sample MISO on rising edge (during CLK_LOW to CLK_HIGH transition)
                    next_shift_reg = {shift_reg[6:0], miso};
                    next_bit_count = bit_count + 1;
                    next_state = CLK_HIGH;
                end
            endcase
        end

        CLK_HIGH: begin
            // SCLK high phase
            sclk = 1'b1;
            mosi = shift_reg[7];  // Continue outputting same bit

            // Mealy output: Data is stable during high phase
            next_state = CLK_LOW;
        end

        DONE_ST: begin
            done = 1'b1;  // Mealy output: done signal
            busy = 1'b0;
            rx_data = shift_reg;
            case (start)
                1'b0: next_state = IDLE;  // Return to idle when start cleared
                default: next_state = DONE_ST;
            endcase
        end
    endcase
end

endmodule,"module spi_master_mealy_asserts  (input logic clk,

module mealy_traffic_controller (
    input  logic clk,
    input  logic rst_n,
    input  logic timer_expired,
    input  logic pedestrian_req,
    output logic main_green,
    output logic main_yellow,
    output logic main_red,
    output logic walk,
    output logic dont_walk
);

    // State encoding
    typedef enum logic [1:0] {
        GREEN,      // Main road green
        YELLOW,     // Main road yellow
        RED,        // Main road red
        PED_WALK    // Pedestrian walking
    } state_t;

    state_t current_state, next_state;

    // Sequential block: state update
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= GREEN;
            1'b1: current_state <= next_state;
        endcase
    end

    // Combinational block: next state logic with timing conditions
    always_comb begin
        next_state = current_state;

        case (current_state)
            GREEN: begin
                // Go to yellow when timer expires OR pedestrian request
                case (timer_expired || pedestrian_req)
                    1'b1: next_state = YELLOW;
                endcase
            end

            YELLOW: begin
                // Always go to red after yellow timer expires
                case (timer_expired)
                    1'b1: next_state = RED;
                endcase
            end

            RED: begin
                // Go to pedestrian walk if request pending
                case (pedestrian_req)
                    1'b1: next_state = PED_WALK;
                endcase

                case (timer_expired && !pedestrian_req)
                    1'b1: next_state = GREEN;
                endcase
            end

            PED_WALK: begin
                // Return to green after walk timer expires
                case (timer_expired)
                    1'b1: next_state = GREEN;
                endcase
            end
        endcase
    end

    // Combinational block: Mealy outputs based on state and inputs
    always_comb begin
        // Default outputs (all inactive)
        {main_green, main_yellow, main_red} = 3'b000;
        {walk, dont_walk} = 2'b00;

        case (current_state)
            GREEN: begin
                main_green = 1'b1;
                dont_walk = 1'b1;  // Don't walk during main traffic
                // Mealy: Flash don't walk when pedestrian waiting
                case (pedestrian_req)
                    1'b1: dont_walk = ~dont_walk;  // Flashing indication
                endcase
            end

            YELLOW: begin
                main_yellow = 1'b1;
                dont_walk = 1'b1;
            end

            RED: begin
                main_red = 1'b1;
                // Mealy: Pre-walk indication when pedestrian waiting
                case (pedestrian_req)
                    1'b1: dont_walk = ~dont_walk;  // Flashing before walk
                    1'b0: dont_walk = 1'b1;
                endcase
            end

            PED_WALK: begin
                main_red = 1'b1;
                walk = 1'b1;        // Walk signal active
            end
        endcase
    end

endmodule,"module mealy_traffic_controller_asserts  (input logic clk,

// AXI4-Lite Slave Interface - Register File Example
// Uses only case statements (no if/else)
// Demonstrates separate combinational and sequential logic blocks

module axi_lite_slave (
    // Clock and Reset
    input  logic        aclk,
    input  logic        aresetn,

    // AXI4-Lite Write Address Channel
    input  logic [31:0] s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    // AXI4-Lite Write Data Channel
    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    // AXI4-Lite Write Response Channel
    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    // AXI4-Lite Read Address Channel
    input  logic [31:0] s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    // AXI4-Lite Read Data Channel
    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready,

    // User interface to registers
    output logic [31:0] reg0,  // Read/Write register
    output logic [31:0] reg1,  // Read/Write register
    output logic [31:0] reg2,  // Read/Write register
    output logic [31:0] reg3,  // Read/Write register
    input  logic [31:0] reg4   // Read-only register
);

    //=========================================================
    // Internal State Definitions
    //=========================================================
    typedef enum logic [1:0] {
        IDLE,
        WRITE_RESP,
        READ_DATA
    } state_t;

    state_t write_state, read_state;
    state_t write_state_next, read_state_next;

    //=========================================================
    // Register Storage
    //=========================================================
    logic [31:0] reg0_q, reg1_q, reg2_q, reg3_q;
    logic [31:0] reg0_next, reg1_next, reg2_next, reg3_next;

    //=========================================================
    // AXI Interface Registers
    //=========================================================
    logic        awready_q, awready_next;
    logic        wready_q, wready_next;
    logic        bvalid_q, bvalid_next;
    logic [1:0]  bresp_q, bresp_next;

    logic        arready_q, arready_next;
    logic        rvalid_q, rvalid_next;
    logic [1:0]  rresp_q, rresp_next;
    logic [31:0] rdata_q, rdata_next;

    // Address and data storage for transactions
    logic [31:0] awaddr_q, awaddr_next;
    logic [31:0] wdata_q, wdata_next;
    logic [3:0]  wstrb_q, wstrb_next;
    logic [31:0] araddr_q, araddr_next;

    //=========================================================
    // Combinational Logic: Write Channel FSM
    //=========================================================
    always_comb begin
        // Default assignments
        write_state_next = write_state;
        awready_next = 1'b0;
        wready_next  = 1'b0;
        bvalid_next  = bvalid_q;
        bresp_next   = bresp_q;
        awaddr_next  = awaddr_q;
        wdata_next   = wdata_q;
        wstrb_next   = wstrb_q;
        reg0_next = reg0_q;
        reg1_next = reg1_q;
        reg2_next = reg2_q;
        reg3_next = reg3_q;

        case (write_state)
            IDLE: begin
                awready_next = 1'b1;
                wready_next  = 1'b1;

                // Capture address and data when valid
                case ({s_axi_awvalid, s_axi_wvalid})
                    2'b11: begin
                        awaddr_next = s_axi_awaddr;
                        wdata_next  = s_axi_wdata;
                        wstrb_next  = s_axi_wstrb;
                        write_state_next = WRITE_RESP;
                    end
                    default: begin
                        write_state_next = IDLE;
                    end
                endcase
            end

            WRITE_RESP: begin
                bvalid_next = 1'b1;
                bresp_next  = 2'b00;  // OKAY response

                // Perform register write based on address
                case (awaddr_q[7:2])  // 4-byte aligned addresses
                    6'b000000: begin  // Address 0x00
                        reg0_next = wdata_q;
                    end
                    6'b000001: begin  // Address 0x04
                        reg1_next = wdata_q;
                    end
                    6'b000010: begin  // Address 0x08
                        reg2_next = wdata_q;
                    end
                    6'b000011: begin  // Address 0x0C
                        reg3_next = wdata_q;
                    end
                    default: begin
                        // Invalid address - no write
                        bresp_next = 2'b11;  // SLVERR
                    end
                endcase

                case ({bvalid_q, s_axi_bready})
                    2'b11: begin
                        bvalid_next = 1'b0;
                        write_state_next = IDLE;
                    end
                    default: begin
                        write_state_next = WRITE_RESP;
                    end
                endcase
            end
        endcase
    end

    //=========================================================
    // Combinational Logic: Read Channel FSM
    //=========================================================
    always_comb begin
        // Default assignments
        read_state_next = read_state;
        arready_next = 1'b0;
        rvalid_next  = rvalid_q;
        rresp_next   = rresp_q;
        rdata_next   = rdata_q;
        araddr_next  = araddr_q;

        case (read_state)
            IDLE: begin
                arready_next = 1'b1;

                case (s_axi_arvalid)
                    1'b1: begin
                        araddr_next = s_axi_araddr;
                        read_state_next = READ_DATA;
                    end
                    default: begin
                        read_state_next = IDLE;
                    end
                endcase
            end

            READ_DATA: begin
                rvalid_next = 1'b1;
                rresp_next  = 2'b00;  // OKAY response

                // Read data based on address
                case (araddr_q[7:2])  // 4-byte aligned addresses
                    6'b000000: begin  // Address 0x00
                        rdata_next = reg0_q;
                    end
                    6'b000001: begin  // Address 0x04
                        rdata_next = reg1_q;
                    end
                    6'b000010: begin  // Address 0x08
                        rdata_next = reg2_q;
                    end
                    6'b000011: begin  // Address 0x0C
                        rdata_next = reg3_q;
                    end
                    6'b000100: begin  // Address 0x10
                        rdata_next = reg4;  // Read-only register
                    end
                    default: begin
                        rdata_next = 32'hDEADBEEF;
                        rresp_next = 2'b11;  // SLVERR
                    end
                endcase

                case ({rvalid_q, s_axi_rready})
                    2'b11: begin
                        rvalid_next = 1'b0;
                        read_state_next = IDLE;
                    end
                    default: begin
                        read_state_next = READ_DATA;
                    end
                endcase
            end
        endcase
    end

    //=========================================================
    // Output Assignments
    //=========================================================
    assign s_axi_awready = awready_q;
    assign s_axi_wready  = wready_q;
    assign s_axi_bvalid  = bvalid_q;
    assign s_axi_bresp   = bresp_q;

    assign s_axi_arready = arready_q;
    assign s_axi_rvalid  = rvalid_q;
    assign s_axi_rresp   = rresp_q;
    assign s_axi_rdata   = rdata_q;

    assign reg0 = reg0_q;
    assign reg1 = reg1_q;
    assign reg2 = reg2_q;
    assign reg3 = reg3_q;

endmodule,"module axi_lite_slave_asserts  (input logic aclk,

module baud_rate_gen_mealy (
    input logic clk,
    input logic rst_n,
    input logic [7:0] divisor,
    input logic [3:0] fraction,
    output logic baud_tick
);

typedef enum logic [1:0] {IDLE, COUNT, ADJUST} state_t;
state_t state, next_state;
logic [7:0] counter, next_counter;
logic [3:0] frac_acc, next_frac_acc;

// Sequential logic
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: begin
            state <= IDLE;
            counter <= 8'b0;
            frac_acc <= 4'b0;
        end
        1'b1: begin
            state <= next_state;
            counter <= next_counter;
            frac_acc <= next_frac_acc;
        end
    endcase
end

// Combinational logic
always_comb begin
    // Default assignments
    next_state = state;
    next_counter = counter;
    next_frac_acc = frac_acc;
    baud_tick = 1'b0;

    case (state)
        IDLE: begin
            case (divisor != 0)
                1'b1: next_state = COUNT;
            endcase
        end

        COUNT: begin
            case (counter == (divisor - 1))
                1'b1: begin
                    case ((frac_acc + fraction) >= 16)
                        1'b1: begin
                            next_state = ADJUST;
                            baud_tick = 1'b1;  // Mealy: tick with fraction adjust
                        end
                        1'b0: begin
                            next_state = IDLE;
                            baud_tick = 1'b1;  // Mealy: normal tick
                        end
                    endcase
                end
            endcase

            // Counter increment logic (combinational)
            case (state == COUNT)
                1'b1: begin
                    case (counter == (divisor - 1))
                        1'b1: next_counter = 8'b0;
                        1'b0: next_counter = counter + 1;
                    endcase
                end
            endcase
        end

        ADJUST: begin
            next_state = IDLE;
            baud_tick = 1'b1;  // Mealy: extra tick for fractional adjustment
            next_frac_acc = frac_acc + fraction - 16;  // Adjust accumulator
        end
    endcase
end

endmodule,"module baud_rate_gen_mealy_asserts  (input logic clk,

module seq_detector_101_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic detected
);

typedef enum logic [1:0] {S0, S1, S2} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: state <= S0;
        1'b1: state <= next_state;
    endcase
end

// Next state and output logic
always_comb begin
    next_state = state;
    detected = 1'b0;

    case (state)
        S0: begin
            case (din)
                1'b1: next_state = S1;
                1'b0: next_state = S0;
            endcase
        end

        S1: begin
            case (din)
                1'b1: next_state = S1;
                1'b0: next_state = S2;
            endcase
        end

        S2: begin
            case (din)
                1'b1: begin
                    next_state = S1;
                    detected = 1'b1;  // Sequence 101 detected
                end
                1'b0: next_state = S0;
            endcase
        end
    endcase
end
endmodule,"module seq_detector_101_mealy_asserts  (input logic clk,

module pattern_detector_1101 (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic match
);

typedef enum logic [2:0] {S0, S1, S11, S110} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: state <= S0;
        1'b1: state <= next_state;
    endcase
end

// Next state and output logic
always_comb begin
    next_state = state;
    match = 1'b0;

    case (state)
        S0: begin
            case (din)
                1'b1: next_state = S1;
                1'b0: next_state = S0;
            endcase
        end

        S1: begin
            case (din)
                1'b1: next_state = S11;
                1'b0: next_state = S0;
            endcase
        end

        S11: begin
            case (din)
                1'b1: next_state = S11;  // Overlap case
                1'b0: next_state = S110;
            endcase
        end

        S110: begin
            case (din)
                1'b1: begin
                    next_state = S1;      // Last '1' can start new sequence
                    match = 1'b1;         // Pattern 1101 detected
                end
                1'b0: next_state = S0;
            endcase
        end
    endcase
end
endmodule,"module pattern_detector_1101_asserts  (input logic clk,

// OBI Protocol Controller - Case-Statements-Only Implementation
// Implements a simplified OBI master interface with request/response handling
// No if/else statements, no loops - only case statements and combinational/sequential blocks

module obi_protocol_controller (
    // Clock and reset
    input  logic clk,
    input  logic rst_n,

    // OBI Master Interface (to interconnect)
    output logic        obi_cmd_valid,
    input  logic        obi_cmd_ready,
    output logic [31:0] obi_cmd_addr,
    output logic [2:0]  obi_cmd_opc,    // 000: read, 001: write, 010: atomic
    output logic [31:0] obi_cmd_wdata,
    output logic [3:0]  obi_cmd_be,

    input  logic        obi_rsp_valid,
    output logic        obi_rsp_ready,
    input  logic [31:0] obi_rsp_rdata,
    input  logic [2:0]  obi_rsp_err,    // 000: ok, 001: decode error, 010: slave error

    // Local control interface
    input  logic        req_valid,
    output logic        req_ready,
    input  logic [31:0] req_addr,
    input  logic [2:0]  req_opc,
    input  logic [31:0] req_wdata,
    input  logic [3:0]  req_be,

    output logic        rsp_valid,
    input  logic        rsp_ready,
    output logic [31:0] rsp_rdata,
    output logic [2:0]  rsp_err,

    // Status outputs
    output logic [2:0]  state_out,
    output logic        pending_transaction
);

    // State encoding
    typedef enum logic [2:0] {
        IDLE         = 3'b000,
        WAIT_CMD_ACK = 3'b001,
        WAIT_RSP     = 3'b010,
        WAIT_RSP_ACK = 3'b011,
        ERROR_RECOV  = 3'b100
    } state_t;

    state_t current_state, next_state;

    // Transaction storage registers
    logic [31:0] stored_addr;
    logic [2:0]  stored_opc;
    logic [31:0] stored_wdata;
    logic [3:0]  stored_be;

    // Response storage
    logic [31:0] stored_rdata;
    logic [2:0]  stored_err;

    // Counter for error recovery (3-cycle timeout)
    logic [1:0] error_counter;

    // -----------------------------------------------------------------
    // BLOCK 1: Sequential State Register (Clock/Reset)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                current_state <= IDLE;
                error_counter <= 2'b00;
            end
            1'b1: begin
                current_state <= next_state;
                case (current_state)
                    ERROR_RECOV: begin
                        // Increment counter during error recovery
                        case (error_counter)
                            2'b11: error_counter <= 2'b11;
                            default: error_counter <= error_counter + 2'b01;
                        endcase
                    end
                    default: begin
                        error_counter <= 2'b00;
                    end
                endcase
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 2: Next State Logic (Combinational)
    // -----------------------------------------------------------------
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case (req_valid)
                    1'b1: next_state = WAIT_CMD_ACK;
                    1'b0: next_state = IDLE;
                endcase
            end

            WAIT_CMD_ACK: begin
                case (obi_cmd_ready)
                    1'b1: begin
                        case (obi_cmd_opc)
                            3'b010: begin  // Atomic operation requires response
                                next_state = WAIT_RSP;
                            end
                            default: begin  // Read/Write operations
                                case (obi_cmd_opc)
                                    3'b000: next_state = WAIT_RSP;  // Read needs response
                                    3'b001: next_state = WAIT_RSP_ACK; // Write needs response
                                    default: next_state = WAIT_RSP;
                                endcase
                            end
                        endcase
                    end
                    1'b0: next_state = WAIT_CMD_ACK;
                endcase
            end

            WAIT_RSP: begin
                case (obi_rsp_valid)
                    1'b1: begin
                        case (rsp_ready)
                            1'b1: next_state = IDLE;
                            1'b0: next_state = WAIT_RSP_ACK;
                        endcase
                    end
                    1'b0: next_state = WAIT_RSP;
                endcase
            end

            WAIT_RSP_ACK: begin
                case (rsp_ready)
                    1'b1: begin
                        case (obi_rsp_err)
                            3'b000: next_state = IDLE;
                            default: next_state = ERROR_RECOV;
                        endcase
                    end
                    1'b0: next_state = WAIT_RSP_ACK;
                endcase
            end

            ERROR_RECOV: begin
                case (error_counter)
                    2'b11: next_state = IDLE;
                    default: next_state = ERROR_RECOV;
                endcase
            end

            default: next_state = IDLE;
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 3: Transaction Capture & OBI Command Generation (Combinational)
    // -----------------------------------------------------------------
    always_comb begin
        // Default assignments
        obi_cmd_valid = 1'b0;
        obi_cmd_addr = 32'b0;
        obi_cmd_opc = 3'b000;
        obi_cmd_wdata = 32'b0;
        obi_cmd_be = 4'b0000;
        req_ready = 1'b0;

        case (current_state)
            IDLE: begin
                case (req_valid)
                    1'b1: begin
                        req_ready = 1'b1;
                        obi_cmd_valid = 1'b1;
                        obi_cmd_addr = req_addr;
                        obi_cmd_opc = req_opc;
                        obi_cmd_wdata = req_wdata;
                        obi_cmd_be = req_be;
                    end
                    default: begin
                        req_ready = 1'b0;
                    end
                endcase
            end

            WAIT_CMD_ACK: begin
                // Keep driving same command until accepted
                obi_cmd_valid = 1'b1;
                obi_cmd_addr = stored_addr;
                obi_cmd_opc = stored_opc;
                obi_cmd_wdata = stored_wdata;
                obi_cmd_be = stored_be;
                req_ready = 1'b0;
            end

            default: begin
                obi_cmd_valid = 1'b0;
                req_ready = 1'b0;
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 4: Transaction Storage Registers (Sequential)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                stored_addr <= 32'b0;
                stored_opc <= 3'b000;
                stored_wdata <= 32'b0;
                stored_be <= 4'b0000;
            end
            1'b1: begin
                case (current_state)
                    IDLE: begin
                        case (req_valid & req_ready)
                            1'b1: begin
                                stored_addr <= req_addr;
                                stored_opc <= req_opc;
                                stored_wdata <= req_wdata;
                                stored_be <= req_be;
                            end
                            default: begin
                                stored_addr <= stored_addr;
                                stored_opc <= stored_opc;
                                stored_wdata <= stored_wdata;
                                stored_be <= stored_be;
                            end
                        endcase
                    end
                    default: begin
                        stored_addr <= stored_addr;
                        stored_opc <= stored_opc;
                        stored_wdata <= stored_wdata;
                        stored_be <= stored_be;
                    end
                endcase
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 5: Response Capture & OBI Response Handshake (Combinational)
    // -----------------------------------------------------------------
    always_comb begin
        // Default assignments
        obi_rsp_ready = 1'b0;
        rsp_valid = 1'b0;
        rsp_rdata = 32'b0;
        rsp_err = 3'b000;

        case (current_state)
            WAIT_RSP: begin
                case (obi_rsp_valid)
                    1'b1: begin
                        obi_rsp_ready = 1'b1;
                        rsp_valid = 1'b1;
                        rsp_rdata = obi_rsp_rdata;
                        rsp_err = obi_rsp_err;
                    end
                    default: begin
                        obi_rsp_ready = 1'b0;
                        rsp_valid = 1'b0;
                    end
                endcase
            end

            WAIT_RSP_ACK: begin
                // Keep response valid until consumed
                obi_rsp_ready = 1'b0;
                rsp_valid = 1'b1;
                rsp_rdata = stored_rdata;
                rsp_err = stored_err;
            end

            default: begin
                obi_rsp_ready = 1'b0;
                rsp_valid = 1'b0;
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 6: Response Storage Registers (Sequential)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                stored_rdata <= 32'b0;
                stored_err <= 3'b000;
            end
            1'b1: begin
                case (current_state)
                    WAIT_RSP: begin
                        case (obi_rsp_valid)
                            1'b1: begin
                                stored_rdata <= obi_rsp_rdata;
                                stored_err <= obi_rsp_err;
                            end
                            default: begin
                                stored_rdata <= stored_rdata;
                                stored_err <= stored_err;
                            end
                        endcase
                    end
                    default: begin
                        stored_rdata <= stored_rdata;
                        stored_err <= stored_err;
                    end
                endcase
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 7: Status Outputs (Combinational)
    // -----------------------------------------------------------------
    always_comb begin
        state_out = current_state;

        case (current_state)
            IDLE: begin
                pending_transaction = 1'b0;
            end
            default: begin
                pending_transaction = 1'b1;
            end
        endcase
    end

endmodule,"module obi_protocol_controller_asserts  (input logic clk,

module pwm_generator_mealy (
    input logic clk,
    input logic rst_n,
    input logic [7:0] period,
    input logic [7:0] duty_cycle,
    input logic update_duty,
    output logic pwm_out
);

typedef enum logic [1:0] {HIGH, LOW, UPDATE} state_t;
state_t state, next_state;
logic [7:0] counter, next_counter;
logic [7:0] current_duty, next_current_duty;

// Sequential logic
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: begin
            state <= LOW;
            counter <= 8'b0;
            current_duty <= 8'b0;
        end
        1'b1: begin
            state <= next_state;
            counter <= next_counter;
            current_duty <= next_current_duty;
        end
    endcase
end

// Combinational logic
always_comb begin
    // Default assignments
    next_state = state;
    next_counter = counter;
    next_current_duty = current_duty;
    pwm_out = 1'b0;

    // Counter increment (always increments unless reset)
    next_counter = counter + 1;

    // Duty cycle update
    case (update_duty)
        1'b1: next_current_duty = duty_cycle;
        default: next_current_duty = current_duty;
    endcase

    case (state)
        HIGH: begin
            pwm_out = 1'b1;

            // Check for end of high period
            case (counter == (current_duty - 1))
                1'b1: begin
                    next_state = LOW;
                    pwm_out = 1'b0;  // Mealy: immediate transition
                end
            endcase

            // Mealy: immediate duty cycle update during HIGH state
            case (update_duty && (counter < duty_cycle))
                1'b1: pwm_out = 1'b1;
            endcase
        end

        LOW: begin
            pwm_out = 1'b0;

            // Check for end of low period
            case (counter == (period - 1))
                1'b1: begin
                    next_state = HIGH;
                    next_counter = 8'b0;
                    pwm_out = 1'b1;  // Mealy: immediate transition
                end
            endcase

            // Mealy: update request during LOW state
            case (update_duty && (duty_cycle > 0))
                1'b1: next_state = UPDATE;
            endcase
        end

        UPDATE: begin
            pwm_out = 1'b1;  // Mealy: immediate response to new duty cycle
            next_state = HIGH;
            next_counter = 8'b0;
        end
    endcase
end

endmodule,"module pwm_generator_mealy_asserts  (input logic clk,

// Mealy FSM: Weapons System Controller
// Tracks: Safe Mode -> Armed -> Fire
// Outputs depend on both state and input (Mealy)
// All conditional logic implemented with case statements only
module weapons_system (
    input  logic clk,
    input  logic rst_n,
    input  logic arm_switch,    // 1: arm command
    input  logic trigger,       // 1: fire command
    input  logic safety_bypass, // 1: override safety
    output logic fire_enable,   // 1: weapon can fire
    output logic armed_led,     // 1: armed indicator
    output logic fault          // 1: illegal condition
);

    // State encoding
    typedef enum logic [1:0] {
        SAFE   = 2'b00,
        ARMED  = 2'b01,
        FAULT  = 2'b10
    } state_t;

    state_t curr_state, next_state;

    // --------------------------------------------------
    // Sequential block: State register (synchronous)
    // --------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: curr_state <= SAFE;
            1'b1: curr_state <= next_state;
        endcase
    end

    // --------------------------------------------------
    // Combinational block 1: Next state logic
    // All conditional logic via case statements
    // --------------------------------------------------
    always_comb begin
        next_state = curr_state;  // default: stay

        case (curr_state)
            SAFE: begin
                case ({arm_switch, safety_bypass})
                    2'b10: next_state = ARMED;   // arm without bypass
                    2'b11: next_state = FAULT;   // arm with bypass = unsafe
                    default: next_state = SAFE;
                endcase
            end
            ARMED: begin
                case ({trigger, arm_switch})
                    2'b10: next_state = SAFE;    // trigger fired
                    2'b00: next_state = SAFE;    // arm_switch turned off
                    default: next_state = ARMED;
                endcase
            end
            FAULT: begin
                next_state = FAULT;   // latch fault until reset
            end
        endcase
    end

    // --------------------------------------------------
    // Combinational block 2: Mealy + Moore outputs
    // All conditional logic via case statements
    // --------------------------------------------------
    always_comb begin
        // Defaults
        fire_enable = 1'b0;
        armed_led   = 1'b0;
        fault       = 1'b0;

        case (curr_state)
            SAFE: begin
                armed_led = 1'b0;
                // Mealy: trigger with safety_bypass causes fault
                case ({trigger, safety_bypass})
                    2'b11: fault = 1'b1;
                    default: fault = 1'b0;
                endcase
                // No fire in SAFE state
                fire_enable = 1'b0;
            end

            ARMED: begin
                armed_led = 1'b1;
                // Mealy: fire_enable active when trigger pressed
                case (trigger)
                    1'b1: fire_enable = 1'b1;
                    default: fire_enable = 1'b0;
                endcase
                // Armed LED turns off if arm_switch deasserted
                case (arm_switch)
                    1'b0: armed_led = 1'b0;
                    default: armed_led = 1'b1;
                endcase
            end

            FAULT: begin
                fault = 1'b1;
                armed_led = 1'b0;
                fire_enable = 1'b0;
            end
        endcase
    end

endmodule,"module weapons_system_asserts  (input logic clk,

module seq_detector_1001_nonoverlap (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic detected
);

typedef enum logic [2:0] {S0, S1, S10, S100} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: state <= S0;
        1'b1: state <= next_state;
    endcase
end

// Next state and output logic
always_comb begin
    next_state = state;
    detected = 1'b0;

    case (state)
        S0: begin
            case (din)
                1'b1: next_state = S1;
                1'b0: next_state = S0;
            endcase
        end

        S1: begin
            case (din)
                1'b1: next_state = S1;
                1'b0: next_state = S10;
            endcase
        end

        S10: begin
            case (din)
                1'b1: next_state = S1;
                1'b0: next_state = S100;
            endcase
        end

        S100: begin
            case (din)
                1'b1: begin
                    next_state = S1;   // Start new sequence from last '1'
                    detected = 1'b1;   // Pattern "1001" detected
                end
                1'b0: next_state = S0; // Reset if next bit is 0
            endcase
        end
    endcase
end
endmodule,"module seq_detector_1001_nonoverlap_asserts  (input logic clk,

module uart_sampler_mealy (
    input logic clk,
    input logic rst_n,
    input logic rx_line,
    input logic sample_enable,
    output logic bit_value,
    output logic bit_ready
);

typedef enum logic [2:0] {IDLE, START, MIDDLE, SAMPLE} state_t;
state_t state, next_state;
logic [2:0] oversample_count, next_oversample_count;

// Sequential logic
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: begin
            state <= IDLE;
            oversample_count <= 3'b0;
        end
        1'b1: begin
            state <= next_state;
            oversample_count <= next_oversample_count;
        end
    endcase
end

// Combinational logic
always_comb begin
    // Default assignments
    next_state = state;
    next_oversample_count = oversample_count;
    bit_value = 1'b0;
    bit_ready = 1'b0;

    // Counter increment logic
    case (sample_enable)
        1'b1: next_oversample_count = oversample_count + 1;
        default: next_oversample_count = oversample_count;
    endcase

    case (state)
        IDLE: begin
            case (!rx_line && sample_enable)  // Start bit detected
                1'b1: next_state = START;
            endcase
        end

        START: begin
            case (sample_enable)
                1'b1: begin
                    case (oversample_count == 3'b100)  // Middle of start bit
                        1'b1: next_state = MIDDLE;
                    endcase
                end
            endcase
        end

        MIDDLE: begin
            case (sample_enable)
                1'b1: begin
                    case (oversample_count == 3'b111)  // Sample point
                        1'b1: begin
                            next_state = SAMPLE;
                            bit_value = rx_line;  // Mealy: sample the bit
                            bit_ready = 1'b1;     // Mealy: bit ready immediately
                        end
                    endcase
                end
            endcase
        end

        SAMPLE: begin
            case (sample_enable)
                1'b1: begin
                    case (oversample_count == 3'b111)
                        1'b1: next_state = IDLE;
                        1'b0: next_state = MIDDLE;
                    endcase
                end
            endcase
        end
    endcase
end

endmodule,"module uart_sampler_mealy_asserts  (input logic clk,

//=============================================================================
// Defense Protocol Stream Cipher Core
// - Uses ONLY case statements (no if/else, no loops)
// - 4 procedural blocks: 2 combinational, 2 sequential
// - Implements a key stream generator with mode control and integrity check
//=============================================================================

module stream_cipher_core (
    input  logic        clk,
    input  logic        rst_n,

    // Control interface
    input  logic [1:0]  mode,          // 00: IDLE, 01: INIT, 10: ENCRYPT, 11: AUTH
    input  logic        start,

    // Data interface
    input  logic [7:0]  key_in,        // Key byte input
    input  logic [7:0]  data_in,       // Plaintext/Ciphertext byte
    output logic [7:0]  data_out,      // Ciphertext/Plaintext byte
    output logic [15:0] auth_tag,      // Authentication tag output
    output logic        ready,
    output logic        valid
);

    //-------------------------------------------------------------------------
    // Internal state variables
    //-------------------------------------------------------------------------
    logic [1:0]  state, next_state;
    logic [7:0]  lfsr [0:3];          // 4-byte LFSR array (32-bit Galois LFSR)
    logic [7:0]  sbox [0:255];        // S-Box for substitution layer
    logic [15:0] accum;               // Authentication accumulator
    logic [3:0]  byte_cnt;            // Byte counter for key setup
    logic [7:0]  key_stream;

    //-------------------------------------------------------------------------
    // Block 1: Combinational - Next state logic (pure case)
    //-------------------------------------------------------------------------
    always_comb begin
        next_state = state;
        case (state)
            2'b00: begin  // IDLE
                case (start)
                    1'b1: next_state = mode;  // Jump directly to requested mode
                    default: next_state = 2'b00;
                endcase
            end

            2'b01: begin  // INIT (key setup)
                case (byte_cnt)
                    4'b1111: next_state = 2'b00;  // 16 bytes loaded, return to IDLE
                    default:  next_state = 2'b01;
                endcase
            end

            2'b10: begin  // ENCRYPT mode
                case (start)
                    1'b0: next_state = 2'b00;     // Operation complete
                    default: next_state = 2'b10;
                endcase
            end

            2'b11: begin  // AUTH mode (authentication only)
                case (start)
                    1'b0: next_state = 2'b00;
                    default: next_state = 2'b11;
                endcase
            end

            default: next_state = 2'b00;
        endcase
    end

    //-------------------------------------------------------------------------
    // Block 2: Sequential - State and counter update (if/else removed)
    //-------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                state    <= 2'b00;
                byte_cnt <= 4'b0000;
            end
            1'b1: begin
                state <= next_state;
                case (state)
                    2'b01: begin  // During INIT, increment counter
                        byte_cnt <= byte_cnt + 1'b1;
                    end
                    2'b10, 2'b11: begin
                        // Reset counter when starting encryption/authentication
                        case (start)
                            1'b1: byte_cnt <= 4'b0000;
                            default: byte_cnt <= byte_cnt + 1'b1;
                        endcase
                    end
                    default: begin
                        case (state)
                            2'b00: byte_cnt <= 4'b0000;
                            default: byte_cnt <= byte_cnt;
                        endcase
                    end
                endcase
            end
        endcase
    end

    //-------------------------------------------------------------------------
    // Block 3: Sequential - LFSR array, S-Box, and accumulator (if/else removed)
    //-------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                lfsr[0] <= 8'h00;
                lfsr[1] <= 8'h00;
                lfsr[2] <= 8'h00;
                lfsr[3] <= 8'h00;
                accum   <= 16'h0000;
                sbox[0] <= 8'h00;
            end
            1'b1: begin
                case (state)
                    2'b01: begin  // INIT: load key into LFSR and generate S-Box
                        case (byte_cnt)
                            4'b0000: lfsr[0] <= key_in;
                            4'b0001: lfsr[1] <= key_in;
                            4'b0010: lfsr[2] <= key_in;
                            4'b0011: lfsr[3] <= key_in;
                            4'b0100: sbox[0]  <= key_in ^ 8'hA5;
                            4'b0101: sbox[1]  <= key_in ^ 8'h5A;
                            4'b0110: sbox[2]  <= key_in ^ 8'hFF;
                            4'b0111: sbox[3]  <= key_in ^ 8'h00;
                            default: begin
                                // Simple S-Box initialization for remaining entries
                                case (byte_cnt[3:2])
                                    2'b10: sbox[{byte_cnt[3:0]}] <= key_in ^ {byte_cnt[3:0], 4'h0};
                                    2'b11: sbox[{byte_cnt[3:0]}] <= key_in ^ {4'h0, byte_cnt[3:0]};
                                    default: sbox[{byte_cnt[3:0]}] <= key_in ^ byte_cnt[3:0];
                                endcase
                            end
                        endcase
                    end

                    2'b10, 2'b11: begin  // ENCRYPT or AUTH: update LFSR and accumulator
                        // Galois LFSR update: polynomial x^32 + x^22 + x^2 + x + 1
                        // Shift and feedback using byte-wise operations
                        case (byte_cnt[1:0])  // Rotate through bytes each clock
                            2'b00: begin
                                lfsr[0] <= lfsr[1];
                                lfsr[1] <= lfsr[2];
                                lfsr[2] <= lfsr[3];
                                lfsr[3] <= sbox[lfsr[0] ^ {lfsr[3][6:0], lfsr[3][7]}];
                            end
                            2'b01: begin
                                lfsr[0] <= lfsr[1];
                                lfsr[1] <= lfsr[2];
                                lfsr[2] <= lfsr[3];
                                lfsr[3] <= sbox[lfsr[0] ^ (lfsr[3] << 1)];
                            end
                            2'b10: begin
                                lfsr[0] <= lfsr[1];
                                lfsr[1] <= lfsr[2];
                                lfsr[2] <= lfsr[3];
                                lfsr[3] <= sbox[lfsr[0] ^ (lfsr[3] >> 1)];
                            end
                            2'b11: begin
                                lfsr[0] <= lfsr[1];
                                lfsr[1] <= lfsr[2];
                                lfsr[2] <= lfsr[3];
                                lfsr[3] <= sbox[lfsr[0] ^ ~lfsr[3]];
                            end
                        endcase

                        // Authentication accumulator update
                        case (state)
                            2'b11: begin  // AUTH mode: accumulate key stream XOR data
                                accum <= accum + {key_stream ^ data_in, 8'h00};
                            end
                            2'b10: begin  // ENCRYPT mode: accumulate plaintext
                                accum <= accum + {data_in, 8'h00};
                            end
                            default: accum <= accum;
                        endcase
                    end

                    default: begin
                        // Reset accumulator when idle
                        case (mode)
                            2'b00: accum <= 16'h0000;
                            default: accum <= accum;
                        endcase
                    end
                endcase
            end
        endcase
    end


    //-------------------------------------------------------------------------
    // Block 4: Combinational - Output logic and key stream generation (pure case)
    //-------------------------------------------------------------------------
    always_comb begin
        // Default assignments
        key_stream = 8'h00;
        data_out   = 8'h00;
        ready      = 1'b0;
        valid      = 1'b0;
        auth_tag   = 16'h0000;

        case (state)
            2'b00: begin  // IDLE state
                ready = 1'b1;
                case (mode)
                    2'b01: valid = 1'b1;  // Ready for key loading
                    default: valid = 1'b0;
                endcase
            end

            2'b01: begin  // INIT state: key loading
                ready = 1'b0;
                case (byte_cnt)
                    4'b1111: begin
                        valid = 1'b1;
                        ready = 1'b1;  // Key setup complete
                    end
                    default: valid = 1'b0;
                endcase
            end

            2'b10: begin  // ENCRYPT mode
                ready = 1'b0;
                // Generate key stream from LFSR and S-Box
                case (byte_cnt[1:0])
                    2'b00: key_stream = sbox[lfsr[0] ^ lfsr[1]];
                    2'b01: key_stream = sbox[lfsr[1] ^ lfsr[2]];
                    2'b10: key_stream = sbox[lfsr[2] ^ lfsr[3]];
                    2'b11: key_stream = sbox[lfsr[3] ^ lfsr[0]];
                endcase

                // Encrypt/decrypt data
                data_out = data_in ^ key_stream;

                case (start)
                    1'b0: begin  // Operation complete
                        valid = 1'b1;
                        ready = 1'b1;
                        auth_tag = accum;  // Output auth tag at end
                    end
                    default: valid = 1'b1;
                endcase
            end

            2'b11: begin  // AUTH mode (generate authentication tag only)
                ready = 1'b0;
                // Generate key stream for authentication
                case (byte_cnt[1:0])
                    2'b00: key_stream = sbox[lfsr[0] ^ ~lfsr[3]];
                    2'b01: key_stream = sbox[lfsr[1] ^ {lfsr[0][3:0], lfsr[0][7:4]}];
                    2'b10: key_stream = sbox[lfsr[2] ^ lfsr[1]];
                    2'b11: key_stream = sbox[lfsr[3] ^ lfsr[2]];
                endcase

                data_out = data_in;  // Passthrough for auth mode

                case (start)
                    1'b0: begin
                        valid = 1'b1;
                        ready = 1'b1;
                        auth_tag = accum;  // Final authentication tag
                    end
                    default: valid = 1'b1;
                endcase
            end

            default: begin
                ready = 1'b0;
                valid = 1'b0;
            end
        endcase
    end

endmodule,"module stream_cipher_core_asserts  (input logic clk,

// Satellite Telemetry Command Decoder
// Uses only case statements - no if/else, no loops
// Handles command parsing, error detection, execution, and telemetry formatting

module satellite_cmd_decoder (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [7:0]  rx_data,        // Received data byte
    input  logic        rx_valid,       // Valid data strobe
    output logic [15:0] tm_data,        // Telemetry data output
    output logic        tm_valid,       // Telemetry valid strobe
    output logic        cmd_error,      // Command error flag
    output logic        busy            // Decoder busy flag
);

    //-----------------------------------------------------------------
    // State encoding for sequential blocks
    //-----------------------------------------------------------------
    typedef enum logic [2:0] {
        IDLE,
        CMD_BYTE,
        ARG_HIGH,
        ARG_LOW,
        EXECUTE,
        TM_RESPONSE
    } state_t;

    state_t current_state, next_state;

    //-----------------------------------------------------------------
    // Command opcodes (8-bit)
    //-----------------------------------------------------------------
    typedef enum logic [7:0] {
        CMD_NOP          = 8'h00,
        CMD_GET_STATUS   = 8'h01,
        CMD_SET_MODE     = 8'h02,
        CMD_GET_TEMP     = 8'h03,
        CMD_SET_POWER    = 8'h04,
        CMD_GET_VOLTAGE  = 8'h05,
        CMD_SET_BEACON   = 8'h06,
        CMD_GET_ORBIT    = 8'h07,
        CMD_RESET        = 8'hFF
    } cmd_opcode_t;

    //-----------------------------------------------------------------
    // Satellite operational modes
    //-----------------------------------------------------------------
    typedef enum logic [1:0] {
        MODE_SAFE    = 2'b00,
        MODE_NORMAL  = 2'b01,
        MODE_PAYLOAD = 2'b10,
        MODE_EMERG   = 2'b11
    } satellite_mode_t;

    //-----------------------------------------------------------------
    // Internal registers
    //-----------------------------------------------------------------
    logic [7:0]  cmd_register;          // Stores command byte
    logic [7:0]  arg_high_register;     // High byte of argument
    logic [7:0]  arg_low_register;      // Low byte of argument
    logic [15:0] telemetry_register;    // Telemetry data to output
    logic [15:0] status_word;           // Satellite status word

    satellite_mode_t current_mode;
    logic [7:0]    temperature;
    logic [11:0]   bus_voltage;
    logic [7:0]    beacon_rate;
    logic [31:0]   orbit_counter;

    //-----------------------------------------------------------------
    // Block 1: Sequential state machine - State update (case only)
    //-----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case ({rst_n, 1'b1})  // Using concatenation to create case expression
            2'b00: begin  // rst_n is 0 (active low reset)
                current_state <= IDLE;
            end
            2'b01: begin  // rst_n is 1 (normal operation)
                current_state <= next_state;
            end
            default: begin
                current_state <= IDLE;
            end
        endcase
    end

    //-----------------------------------------------------------------
    // Block 2: Combinational next state logic (case only)
    //-----------------------------------------------------------------
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case (rx_valid)
                    1'b1: next_state = CMD_BYTE;
                    default: next_state = IDLE;
                endcase
            end

            CMD_BYTE: begin
                case (cmd_register)
                    CMD_NOP, CMD_RESET: next_state = EXECUTE;
                    CMD_GET_STATUS, CMD_GET_TEMP,
                    CMD_GET_VOLTAGE, CMD_GET_ORBIT: next_state = EXECUTE;
                    CMD_SET_MODE, CMD_SET_POWER, CMD_SET_BEACON: next_state = ARG_HIGH;
                    default: next_state = IDLE;
                endcase
            end

            ARG_HIGH: next_state = ARG_LOW;
            ARG_LOW:  next_state = EXECUTE;
            EXECUTE:  next_state = TM_RESPONSE;
            TM_RESPONSE: begin
                case (tm_valid)
                    1'b1: next_state = IDLE;
                    default: next_state = TM_RESPONSE;
                endcase
            end
            default: next_state = IDLE;
        endcase
    end

    //-----------------------------------------------------------------
    // Block 3: Sequential register updates (case only - no if/else)
    //-----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        // Reset handling using case statement
        case ({rst_n, 1'b1})
            2'b00: begin  // Reset condition
                cmd_register     <= 8'h00;
                arg_high_register <= 8'h00;
                arg_low_register  <= 8'h00;
                status_word      <= 16'h0001;
                current_mode     <= MODE_SAFE;
                temperature      <= 8'h20;
                bus_voltage      <= 12'h500;
                beacon_rate      <= 8'h0A;
                orbit_counter    <= 32'h00000000;
            end

            2'b01: begin  // Normal operation (rst_n = 1)
                case (current_state)
                    IDLE: begin
                        case (rx_valid)
                            1'b1: cmd_register <= rx_data;
                            1'b0: cmd_register <= cmd_register;
                            default: cmd_register <= cmd_register;
                        endcase

                        // Other registers hold their values
                        arg_high_register <= arg_high_register;
                        arg_low_register  <= arg_low_register;
                        status_word       <= status_word;
                        current_mode      <= current_mode;
                        temperature       <= temperature;
                        bus_voltage       <= bus_voltage;
                        beacon_rate       <= beacon_rate;
                        orbit_counter     <= orbit_counter;
                    end

                    CMD_BYTE: begin
                        // Hold all registers
                        cmd_register     <= cmd_register;
                        arg_high_register <= arg_high_register;
                        arg_low_register  <= arg_low_register;
                        status_word       <= status_word;
                        current_mode      <= current_mode;
                        temperature       <= temperature;
                        bus_voltage       <= bus_voltage;
                        beacon_rate       <= beacon_rate;
                        orbit_counter     <= orbit_counter;
                    end

                    ARG_HIGH: begin
                        arg_high_register <= rx_data;
                        // Hold other registers
                        cmd_register     <= cmd_register;
                        arg_low_register  <= arg_low_register;
                        status_word       <= status_word;
                        current_mode      <= current_mode;
                        temperature       <= temperature;
                        bus_voltage       <= bus_voltage;
                        beacon_rate       <= beacon_rate;
                        orbit_counter     <= orbit_counter;
                    end

                    ARG_LOW: begin
                        arg_low_register <= rx_data;
                        // Hold other registers
                        cmd_register     <= cmd_register;
                        arg_high_register <= arg_high_register;
                        status_word       <= status_word;
                        current_mode      <= current_mode;
                        temperature       <= temperature;
                        bus_voltage       <= bus_voltage;
                        beacon_rate       <= beacon_rate;
                        orbit_counter     <= orbit_counter;
                    end

                    EXECUTE: begin
                        case (cmd_register)
                            CMD_NOP: begin
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_GET_STATUS: begin
                                status_word[15:8] <= {2'b00, current_mode, 4'b0000};
                                status_word[7:0]  <= 8'hA5;
                                // Hold other registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_SET_MODE: begin
                                case (arg_high_register[1:0])
                                    2'b00: current_mode <= MODE_SAFE;
                                    2'b01: current_mode <= MODE_NORMAL;
                                    2'b10: current_mode <= MODE_PAYLOAD;
                                    2'b11: current_mode <= MODE_EMERG;
                                    default: current_mode <= MODE_SAFE;
                                endcase
                                // Hold other registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_GET_TEMP: begin
                                temperature <= temperature + 8'h01;
                                // Hold other registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_SET_POWER: begin
                                case (arg_high_register[0])
                                    1'b0: bus_voltage <= 12'h000;
                                    1'b1: bus_voltage <= 12'h500;
                                    default: bus_voltage <= bus_voltage;
                                endcase
                                // Hold other registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_GET_VOLTAGE: begin
                                // Voltage reading is already in bus_voltage
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_SET_BEACON: begin
                                beacon_rate <= arg_high_register;
                                // Hold other registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_GET_ORBIT: begin
                                orbit_counter <= orbit_counter + 32'h00000001;
                                // Hold other registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                            end

                            CMD_RESET: begin
                                status_word   <= 16'h0001;
                                current_mode  <= MODE_SAFE;
                                temperature   <= 8'h20;
                                bus_voltage   <= 12'h500;
                                beacon_rate   <= 8'h0A;
                                orbit_counter <= 32'h00000000;
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                            end

                            default: begin
                                // Invalid command - hold all registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end
                        endcase
                    end

                    TM_RESPONSE: begin
                        // Hold all registers during TM response
                        cmd_register     <= cmd_register;
                        arg_high_register <= arg_high_register;
                        arg_low_register  <= arg_low_register;
                        status_word       <= status_word;
                        current_mode      <= current_mode;
                        temperature       <= temperature;
                        bus_voltage       <= bus_voltage;
                        beacon_rate       <= beacon_rate;
                        orbit_counter     <= orbit_counter;
                    end

                    default: begin
                        // Default hold for all registers
                        cmd_register     <= cmd_register;
                        arg_high_register <= arg_high_register;
                        arg_low_register  <= arg_low_register;
                        status_word       <= status_word;
                        current_mode      <= current_mode;
                        temperature       <= temperature;
                        bus_voltage       <= bus_voltage;
                        beacon_rate       <= beacon_rate;
                        orbit_counter     <= orbit_counter;
                    end
                endcase
            end

            default: begin
                // Default reset condition
                cmd_register     <= 8'h00;
                arg_high_register <= 8'h00;
                arg_low_register  <= 8'h00;
                status_word      <= 16'h0001;
                current_mode     <= MODE_SAFE;
                temperature      <= 8'h20;
                bus_voltage      <= 12'h500;
                beacon_rate      <= 8'h0A;
                orbit_counter    <= 32'h00000000;
            end
        endcase
    end

    //-----------------------------------------------------------------
    // Block 4: Combinational output and telemetry formatting (case only)
    //-----------------------------------------------------------------
    always_comb begin
        // Default assignments
        telemetry_register = 16'h0000;
        tm_valid = 1'b0;
        cmd_error = 1'b0;
        busy = (current_state != IDLE);

        case (current_state)
            IDLE: begin
                cmd_error = 1'b0;
            end

            CMD_BYTE: begin
                case (cmd_register)
                    CMD_NOP, CMD_GET_STATUS, CMD_GET_TEMP,
                    CMD_GET_VOLTAGE, CMD_GET_ORBIT, CMD_RESET: begin
                        cmd_error = 1'b0;
                    end
                    CMD_SET_MODE, CMD_SET_POWER, CMD_SET_BEACON: begin
                        cmd_error = 1'b0;
                    end
                    default: begin
                        cmd_error = 1'b1;  // Unknown command
                    end
                endcase
            end

            ARG_HIGH, ARG_LOW: begin
                // Argument reception in progress
            end

            EXECUTE: begin
                case (cmd_register)
                    CMD_GET_STATUS: begin
                        telemetry_register = status_word;
                    end

                    CMD_GET_TEMP: begin
                        telemetry_register = {8'h00, temperature};
                    end

                    CMD_GET_VOLTAGE: begin
                        telemetry_register = {4'h0, bus_voltage};
                    end

                    CMD_GET_ORBIT: begin
                        telemetry_register = orbit_counter[15:0];
                    end

                    CMD_SET_MODE, CMD_SET_POWER, CMD_SET_BEACON: begin
                        telemetry_register = 16'hACCE;  // Command accepted
                    end

                    CMD_NOP: begin
                        telemetry_register = 16'hDEAD;
                    end

                    CMD_RESET: begin
                        telemetry_register = 16'hBEEF;  // Reset acknowledged
                    end

                    default: begin
                        telemetry_register = 16'hFFFF;  // Error response
                    end
                endcase
            end

            TM_RESPONSE: begin
                tm_valid = 1'b1;
                telemetry_register = telemetry_register;  // Hold value
            end

            default: begin
                telemetry_register = 16'h0000;
            end
        endcase
    end

    //-----------------------------------------------------------------
    // Block 5: Output assignment (combinational)
    //-----------------------------------------------------------------
    assign tm_data = telemetry_register;

endmodule,"module satellite_cmd_decoder_asserts  (input logic clk,
